+    <a href="@(frontPage?.Url() ?? "/")" class="text-sm text-blue-700 hover:underline">&larr; Back to Blog</a>
+    <h1 class="text-4xl font-bold mt-4 mb-2">@Model.Name</h1>
+    <p class="text-sm text-slate-500 mb-6">@Model.PublishDate.ToString("MMMM d, yyyy")</p>
